from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oauth2_provider.models import AccessToken
import time

class RFC7662TokenIntrospectView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        token_string = request.data.get("token")
        if not token_string:
            return Response({"active": False}, status=status.HTTP_200_OK)

        calling_application = getattr(request.auth, 'application', None) or getattr(request, 'client', None)
        # Restrict introspection: token must belong to calling application or authorized audience
        access_token = AccessToken.objects.select_related("application", "user").filter(
            token=token_string,
            application=calling_application
        ).first()
        if not access_token or access_token.is_expired():
            return Response({"active": False}, status=status.HTTP_200_OK)

        return Response({
            "active": True,
            "scope": access_token.scope,
            "client_id": access_token.application.client_id,
            "sub": access_token.user.username if access_token.user else None,
            "exp": int(access_token.expires.timestamp())
        }, status=status.HTTP_200_OK)
